\text{净资产收益率（ROE）} = 
\underbrace{\frac{\text{净利润}}{\text{营业总收入}}}_{\text{销售净利率}} 
\times 
\underbrace{\frac{\text{营业总收入}}{\text{平均总资产}}}_{\text{总资产周转率}} 
\times 
\underbrace{\frac{\text{平均总资产}}{\text{平均股东权益}}}_{\text{权益乘数}},
\text{平均总资产}=\frac{\left ( \text{期初总资产}+\text{期末总资产} \right )}{2},
\text{平均股东权益}=\frac{\left ( \text{期初所有者权益合计}+\text{期末所有者权益合计} \right )}{2}

\text{应收账款周转率} = \frac{\text{营业收入}}{\text{平均应收账款净额}}
\text{存货周转率} = \frac{\text{营业成本}}{\text{平均存货余额}}
\text{应付账款周转率} = \frac{\text{营业成本}}{\text{平均应付账款余额}}
\text{平均应收账款净额} = \frac{\text{期末应收账款}+\text{期初应收账款}}{\text{2}}
\text{平均存货余额} = \frac{\text{期末存货}+\text{期初存货}}{\text{2}}
\text{平均应付账款余额} = \frac{\text{期末应付账款}+\text{期初应付账款}}{\text{2}}\text{应收账款周转天数} = \frac{\text{360}}{\text{应收账款周转率}}
\text{应付账款周转天数} = \frac{\text{360}}{\text{应付账款周转率}}
\text{存货周转天数} = \frac{\text{360}}{\text{存货周转率}}
\text{现金循环周期} = \text{应收账款周转天数}+\text{存货周转天数}-\text{应付账款周转天数}

\text{长期资本负债率} = \frac{\text{非流动负债}}{\text{非流动负债} + \text{所有者权益}}
\text{利息保障倍数（EBIT版）} = \frac{\text{EBIT}}{\text{利息费用}}\text{现金利息保障倍数} = \frac{\text{经营活动现金流量净额} + \text{支付的利息} + \text{支付的所得税}}{\text{支付的利息}}
\text{到期债务偿付率} = \frac{\text{经营活动现金流量净额}}{\text{本期到期有息债务本金} + \text{利息支付}}
\text{现金比率} = \frac{\text{货币资金} + \text{交易性金融资产}}{\text{流动负债}} \times 100\%
\text{营运资本周转率} = \frac{\text{营业收入}}{\text{平均营运资本}}
\text{营运资本} = \text{流动资产} - \text{流动负债}
\text{平均营运资本} = \frac{\text{期初营运资本}+\text{期末营运资本}}{2}
